import{G as e,K as t,n,ot as r}from"./chunks/framework.BZpZOnGD.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"documentalist-lab/bob-as-documentalist/02-identify-issues.md","filePath":"documentalist-lab/bob-as-documentalist/02-identify-issues.md"}`),a={name:`documentalist-lab/bob-as-documentalist/02-identify-issues.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="📋-the-situation" tabindex="-1">📋 The Situation <a class="header-anchor" href="#📋-the-situation" aria-label="Permalink to “📋 The Situation”">​</a></h2><p>Now that you have the full list, you want Bob to flag anything suspicious — duplicates, legacy classes, naming inconsistencies, demo classes that shouldn&#39;t be in production.</p><h2 id="💬-prompt-to-bob" tabindex="-1">💬 Prompt to Bob <a class="header-anchor" href="#💬-prompt-to-bob" aria-label="Permalink to “💬 Prompt to Bob”">​</a></h2><ol><li><p>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>Ask</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Looking at that class inventory, which classes look like duplicates, </span></span>
<span class="line"><span>legacy classes, or things we should clean up? I&#39;m particularly worried </span></span>
<span class="line"><span>about classes that seem to serve the same purpose. Only focus on classes </span></span>
<span class="line"><span>in the Tax, HR and Contracts domain.</span></span></code></pre></div></li></ol><h2 id="🔍-what-bob-does-behind-the-scenes" tabindex="-1">🔍 What Bob Does Behind the Scenes <a class="header-anchor" href="#🔍-what-bob-does-behind-the-scenes" aria-label="Permalink to “🔍 What Bob Does Behind the Scenes”">​</a></h2><ul><li>Analyzes the inventory of class names and descriptions for functional overlap, redundancy, and structural patterns across the requested domains (Tax, HR, Contracts).</li><li>Evaluates class design anti-patterns, such as encoding status or frequency into class names rather than metadata properties.</li><li>Compares domain granularity and flags naming inconsistencies across the repository.</li></ul><h2 id="✅-expected-output-from-bob" tabindex="-1">✅ Expected Output from Bob <a class="header-anchor" href="#✅-expected-output-from-bob" aria-label="Permalink to “✅ Expected Output from Bob”">​</a></h2><p>Bob should return a structured catalog similar to:</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Based on the class definitions and symbolic names in the repository across the <strong>Tax Administration</strong>, <strong>HR</strong>, and <strong>Contracts</strong> domains, here is an analysis of potential duplicates, functional overlaps, and candidates for cleanup or consolidation.</p><hr><h4 id="_1-high-priority-direct-redundancies-overlapping-purpose" tabindex="-1">1. High Priority: Direct Redundancies &amp; Overlapping Purpose <a class="header-anchor" href="#_1-high-priority-direct-redundancies-overlapping-purpose" aria-label="Permalink to “1. High Priority: Direct Redundancies &amp; Overlapping Purpose”">​</a></h4><p>These classes represent cases where two classes perform virtually the same function and create ambiguity during document filing.</p><h5 id="a-btw-vat-filings" tabindex="-1">A. BTW (VAT) Filings <a class="header-anchor" href="#a-btw-vat-filings" aria-label="Permalink to “A. BTW (VAT) Filings”">​</a></h5><ul><li><strong><code>AangifteBTWKwartaal</code> vs. <code>AangifteBTW</code></strong><ul><li><strong>The Issue:</strong> <code>AangifteBTW</code> is already defined as a periodic VAT return covering monthly, quarterly, or annual filings. <code>AangifteBTWKwartaal</code> was created specifically for quarterly returns with identical content requirements.</li><li><strong>Recommendation:</strong> <strong>Retire <code>AangifteBTWKwartaal</code></strong>. File all VAT returns under <code>AangifteBTW</code> and use a metadata property (e.g., <code>PeriodType</code> or <code>Frequency</code>: <em>Maand / Kwartaal / Jaar</em>) to distinguish filing periods.</li></ul></li></ul><hr><h4 id="_2-medium-priority-generic-vs-specialized-class-ambiguity" tabindex="-1">2. Medium Priority: Generic vs. Specialized Class Ambiguity <a class="header-anchor" href="#_2-medium-priority-generic-vs-specialized-class-ambiguity" aria-label="Permalink to “2. Medium Priority: Generic vs. Specialized Class Ambiguity”">​</a></h4><p>In these areas, both generic parent-style classes and highly specific subtype classes coexist, leading to inconsistent document classification.</p><h5 id="a-customs-declarations-douane" tabindex="-1">A. Customs Declarations (<em>Douane</em>) <a class="header-anchor" href="#a-customs-declarations-douane" aria-label="Permalink to “A. Customs Declarations (Douane)”">​</a></h5><ul><li><strong><code>Douaneaangifte</code> vs. <code>InvoerAangifte</code>, <code>UitvoerAangifte</code>, <code>VereenvoudigdeDouaneaangifte</code></strong><ul><li><strong>The Issue:</strong> <code>Douaneaangifte</code> is a broad, generic customs declaration class covering both import and export. However, specialized classes (<code>InvoerAangifte</code>, <code>UitvoerAangifte</code>, and <code>VereenvoudigdeDouaneaangifte</code>) also exist.</li><li><strong>Recommendation:</strong> Decide on a single classification strategy: <ul><li><strong>Option 1 (Consolidated):</strong> Standardize on <code>Douaneaangifte</code> as the single class, using metadata properties (<code>DeclarationType</code>: <em>Invoer / Uitvoer / Vereenvoudigd / Transit</em>).</li><li><strong>Option 2 (Specialized):</strong> Keep the specific classes and deprecate/retire the generic <code>Douaneaangifte</code> to force precise classification.</li></ul></li></ul></li></ul><h5 id="b-financial-statements" tabindex="-1">B. Financial Statements <a class="header-anchor" href="#b-financial-statements" aria-label="Permalink to “B. Financial Statements”">​</a></h5><ul><li><strong><code>WinstEnVerliesrekening</code> vs. <code>JaarrekeningDocument</code></strong><ul><li><strong>The Issue:</strong> <code>JaarrekeningDocument</code> holds complete annual financial statements (including balance sheet and P&amp;L), while <code>WinstEnVerliesrekening</code> is a standalone class for just the P&amp;L statement (often filed merely as an appendix to corporate tax returns or annual accounts).</li><li><strong>Recommendation:</strong> Review whether standalone P&amp;L statements genuinely require a separate class or if they should be filed under <code>JaarrekeningDocument</code> with a document sub-type property.</li></ul></li></ul><h5 id="c-corporate-payroll-corrections-preliminary-filings" tabindex="-1">C. Corporate &amp; Payroll Corrections / Preliminary Filings <a class="header-anchor" href="#c-corporate-payroll-corrections-preliminary-filings" aria-label="Permalink to “C. Corporate &amp; Payroll Corrections / Preliminary Filings”">​</a></h5><ul><li><strong><code>CorrectieAangifteLoonheffingen</code> vs. <code>AangifteLoonheffingen</code></strong><ul><li><strong>The Issue:</strong> <code>CorrectieAangifteLoonheffingen</code> is a dedicated class just for amended payroll tax returns. Notice that for VAT, amendments use a separate report (<code>BTWCorrectiemelding</code>), while corporate tax does not have a separate correction class.</li><li><strong>Recommendation:</strong> Standardize correction handling across tax types. Filing amended returns under <code>AangifteLoonheffingen</code> with a metadata flag (<code>IsCorrection: Boolean</code> or <code>FilingStatus</code>) would simplify the schema.</li></ul></li></ul><hr><h4 id="_3-domain-granularity-imbalance-architectural-observations" tabindex="-1">3. Domain Granularity Imbalance &amp; Architectural Observations <a class="header-anchor" href="#_3-domain-granularity-imbalance-architectural-observations" aria-label="Permalink to “3. Domain Granularity Imbalance &amp; Architectural Observations”">​</a></h4><table tabindex="0"><thead><tr><th>Domain</th><th style="text-align:center;">Class Count</th><th>Granularity Assessment</th></tr></thead><tbody><tr><td><strong>Tax Administration</strong></td><td style="text-align:center;"><strong>30</strong></td><td><strong>Over-specialized</strong>: Contains 30 distinct classes, with separate classes for filing frequencies, correction notices, rulings, advice reports, and specific taxes.</td></tr><tr><td><strong>HR</strong></td><td style="text-align:center;"><strong>1</strong></td><td><strong>Under-specialized / Catch-all</strong>: A single generic class (<code>HRDocument</code>) holds all employee records (employment contracts, performance appraisals, leave forms, certifications, correspondence).</td></tr><tr><td><strong>Contracts / Legal</strong></td><td style="text-align:center;"><strong>1</strong></td><td><strong>Under-specialized / Catch-all</strong>: A single generic class (<code>Contract</code>) holds all vendor agreements, customer contracts, NDAs, and SLAs.</td></tr></tbody></table><h5 id="inconsistent-naming-conventions" tabindex="-1">Inconsistent Naming Conventions <a class="header-anchor" href="#inconsistent-naming-conventions" aria-label="Permalink to “Inconsistent Naming Conventions”">​</a></h5><ul><li><strong><code>VoorlopigAanslagIB</code> vs. <code>AanslagBiljet</code> / <code>VoortaxatieVennootschapsbelasting</code>:</strong><ul><li>Some tax classes use abbreviations in their symbolic names (<code>VoorlopigAanslagIB</code>, <code>AangifteBPM</code>), while others spell out full terms (<code>VoortaxatieVennootschapsbelasting</code>, <code>AangifteInkomstenbelasting</code>).</li><li><code>VoorlopigAanslagIB</code> drops the trailing &quot;e&quot; (<code>Voorlopig</code> instead of <code>Voorlopige</code>), whereas <code>VereenvoudigdeDouaneaangifte</code> retains full spelling.</li></ul></li></ul><hr><h4 id="summary-checklist-for-cleanup" tabindex="-1">Summary Checklist for Cleanup <a class="header-anchor" href="#summary-checklist-for-cleanup" aria-label="Permalink to “Summary Checklist for Cleanup”">​</a></h4><ol><li>🗑️ <strong>Consolidate <code>AangifteBTWKwartaal</code> into <code>AangifteBTW</code></strong> (Eliminates obvious duplicate purpose).</li><li>🧹 <strong>Resolve Customs class overlap</strong> (<code>Douaneaangifte</code> vs. <code>InvoerAangifte</code> / <code>UitvoerAangifte</code> / <code>VereenvoudigdeDouaneaangifte</code>).</li><li>🔄 <strong>Standardize corrections and preliminary filings</strong> (Decide whether correction/preliminary status is a class or a metadata property).</li><li>⚖️ <strong>Evaluate HR &amp; Contract specialization</strong> (Consider whether HR and Contracts need subclassing or metadata schemas to match business requirements).</li></ol></div><h2 id="💡-key-insights" tabindex="-1">💡 Key Insights <a class="header-anchor" href="#💡-key-insights" aria-label="Permalink to “💡 Key Insights”">​</a></h2><ul><li><strong>The &quot;Class vs. Property&quot; Design Trap:</strong> Class proliferation often occurs when variations like filing periods, frequencies, or correction statuses are modeled as distinct classes rather than metadata properties on a single parent class.</li><li><strong>Granularity Imbalance:</strong> Repositories frequently exhibit uneven maturity across domains — some areas suffer from over-specialization with redundant classes, while others rely on overly generic catch-all classes.</li><li><strong>AI-Assisted Governance:</strong> While individual AI responses may phrase or prioritize recommendations slightly differently across runs, analyzing the deterministic repository structure consistently surfaces actionable architecture and cleanup opportunities.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};